SELECT game_id AS "gameId", sequence_id AS "sequenceId", provider_id AS "providerId", sequence_key AS "sequenceKey", display_name AS "displayName", change_revision AS "changeRevision", updated_at AS "updatedAt" FROM public.effect_sequences WHERE game_id = #{gameId}
AND provider_id = #{providerId}
ORDER BY provider_id, sequence_id
